using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class CastellanSuccessionTests
{
    static readonly EntityId Home=new("site:kofu"),Owner=new("org:takeda"),Old=new("person:shingen"),Heir=HistoricalHouseholdCatalog.Edition.People.Single().Id;
    static WorldSession Start(bool heir=false)=>new(NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],heir?Heir.Value:Old.Value,42,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,worldArmyPolicy:NpcArmies.CompactCombatPolicy,economyPolicy:HouseSuccession.Policy));
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
    static void At(WorldSession s,long t){while(s.Seconds<t){long old=s.Seconds;s.SetPaused(false);s.AdvanceTo(t,100000);Assert.True(s.Seconds>old);}}
    static void Succeed(WorldSession s){var id=new EntityId("request:steward-head/"+s.Revision);Good(s.ManageHouseSuccession(new(id,HouseSuccessionAction.Nominate,Owner,Heir),s.PlayerControl,s.Revision));Good(s.ManageHouseSuccession(new(new("request:steward-head-confirm/"+s.Revision),HouseSuccessionAction.Confirm,Owner,Original:id),s.PlayerControl,s.Revision));At(s,s.Seconds+1);}

    static CastellanInput Appoint(WorldSession s,int days=30)=>new(new("request:castle-before/"+s.Revision),CastellanAction.Appoint,Home,Heir,Days:days);
    static CastellanInput Renew(WorldSession s,EntityId old,int days=30)=>new(new("request:castle-after/"+s.Revision),CastellanAction.Reauthorize,Home,Old,old,days);
    static void Service(WorldSession s){var bond=s.HouseholdServiceView()!.Releases.Single(b=>b.Subject==Heir);Good(s.ManageHouseholdService(new(new("request:castle-release-service/"+s.Revision),HouseholdServiceAction.Release,Owner,bond.Other,bond.Source),s.PlayerControl,s.Revision));Good(s.ManageHouseholdService(new(new("request:castle-new-service/"+s.Revision),s.PlayerControl==Heir?HouseholdServiceAction.AcceptPledge:HouseholdServiceAction.Pledge,Owner,s.PlayerControl==Heir?Old:Heir),s.PlayerControl,s.Revision));}
    static WorldSession Prepared(bool head=false){var s=Start(head);Good(s.ManageCastellan(Appoint(s),s.PlayerControl,s.Revision));Succeed(s);Service(s);return s;}
    [Theory][InlineData(false)][InlineData(true)]public void DistinctReappointmentPreservesExpiryOwnershipAndHistory(bool head){var s=Prepared(head);var before=s.DiagnosticSnapshot();var old=before.Castellan!.Entries.Single();Assert.False(s.CastellanView()!.Appointments.Single().CanReceive);var i=Renew(s,old.Input.Id);Assert.Contains(s.CastellanReauthorizationView(),c=>c.Agents.Contains(Old));Good(s.ManageCastellan(i,s.PlayerControl,s.Revision));var w=s.DiagnosticSnapshot();Assert.Contains(old,w.Castellan!.Entries);var fresh=w.Castellan.Entries.Last();Assert.Equal(Heir,fresh.Principal);Assert.Equal(Old,fresh.Agent);Assert.Equal(old.Until,fresh.Until);Assert.Equal(ContractJson.Write(before.Memberships),ContractJson.Write(w.Memberships));Assert.Equal(ContractJson.Write(before.ResourceLots),ContractJson.Write(w.ResourceLots));Assert.Equal(ContractJson.Write(before.ServiceBonds),ContractJson.Write(w.ServiceBonds));Assert.False(s.CastellanView()!.Appointments.Single(c=>c.Id==old.Input.Id).CanReceive);new WorldSession(ContractJson.Copy(w));}
    [Fact]public void PoliticalChangeDoesNotAutomaticallyCreatePledgeOrAppointment(){var s=Start(true);var i=Appoint(s);Good(s.ManageCastellan(i,Heir,s.Revision));Succeed(s);Assert.Single(s.DiagnosticSnapshot().Castellan!.Entries);Assert.Null(s.DiagnosticSnapshot().HouseService);Assert.False(s.CastellanView()!.Appointments.Single().CanReceive);Assert.Equal(ResultCode.NotAvailable,s.ManageCastellan(Renew(s,i.Id),Heir,s.Revision).Code);}
    [Fact]public void HeadCanAlreadyReleaseOldAppointmentWithOldAgentPresent(){var s=Start(true);var i=Appoint(s);Good(s.ManageCastellan(i,Heir,s.Revision));Succeed(s);Assert.True(s.CastellanView()!.Appointments.Single().CanRelease);Good(s.ManageCastellan(new(new("request:release-previous-office"),CastellanAction.Release,Home,Appointment:i.Id),Heir,s.Revision));Assert.Empty(s.CastellanReauthorizationView());}
    [Fact]public void OldReportKeepsOldRecipientAndNewStoreDoesNotCopyOldQuantity(){var s=Start(true);var i=Appoint(s);Good(s.ManageCastellan(i,Heir,s.Revision));Good(s.ManageCastellan(new(new("request:old-store"),CastellanAction.ReceiveStore,Home,Appointment:i.Id),Heir,s.Revision));Good(s.SendCastellanReport(new(new("request:old-store-paper"),CastellanReportAction.Report,i.Id),Heir,s.Revision));var paper=s.DiagnosticSnapshot().CastellanReports!.Papers.Single();Succeed(s);Service(s);var fresh=Renew(s,i.Id);Good(s.ManageCastellan(fresh,Heir,s.Revision));Assert.Equal(Old,paper.Recipient);Assert.Contains(paper,s.DiagnosticSnapshot().CastellanReports!.Papers);Assert.Null(s.CastellanView()!.Appointments.Single(c=>c.Id==fresh.Id).Receipt);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void NewCustodyAndNewReportUseActualNewPrincipal(){var s=Prepared();var i=Renew(s,s.DiagnosticSnapshot().Castellan!.Entries[0].Input.Id);Good(s.ManageCastellan(i,Old,s.Revision));var stock=ContractJson.Write(s.DiagnosticSnapshot().Materials);Good(s.ManageCastellan(new(new("request:new-store"),CastellanAction.ReceiveStore,Home,Appointment:i.Id),Old,s.Revision));Good(s.SendCastellanReport(new(new("request:new-store-paper"),CastellanReportAction.Report,i.Id),Old,s.Revision));var p=s.DiagnosticSnapshot().CastellanReports!.Papers.Single();Assert.Equal(Heir,p.Recipient);Assert.Equal(Old,p.Sender);Assert.Equal(i.Id,p.Appointment);Assert.Equal(stock,ContractJson.Write(s.DiagnosticSnapshot().Materials));Assert.Equal(Owner,p.Observation.Owner);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void RepeatedConflictingWrongActorAndStaleOperationsDoNotDuplicate(){var s=Prepared();var i=Renew(s,s.DiagnosticSnapshot().Castellan!.Entries[0].Input.Id);Assert.Equal(ResultCode.StateChanged,s.ManageCastellan(i,Old,s.Revision-1).Code);Assert.Equal(ResultCode.NotAvailable,s.ManageCastellan(i,Heir,s.Revision).Code);Good(s.ManageCastellan(i,Old,s.Revision));Assert.Equal(ResultCode.AlreadyAccepted,s.ManageCastellan(i,Old,s.Revision).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.ManageCastellan(i with{Days=1},Old,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.ManageCastellan(i with{Id=new("request:duplicate-old")},Old,s.Revision).Code);Assert.Equal(2,s.DiagnosticSnapshot().Castellan!.Entries.Length);}
    [Fact]public void ReleasedOldOriginalCannotBeReauthorized(){var s=Start(true);var i=Appoint(s);Good(s.ManageCastellan(i,Heir,s.Revision));Succeed(s);Good(s.ManageCastellan(new(new("request:released-source"),CastellanAction.Release,Home,Appointment:i.Id),Heir,s.Revision));Service(s);Assert.Equal(ResultCode.NotAvailable,s.ManageCastellan(Renew(s,i.Id),Heir,s.Revision).Code);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(31)]public void InvalidDurationOrExpiredOriginalCannotBeRenewed(int n){var s=Prepared();if(n==1)At(s,30*86400);Assert.Equal(ResultCode.NotAvailable,s.ManageCastellan(Renew(s,s.DiagnosticSnapshot().Castellan!.Entries[0].Input.Id,n),Old,s.Revision).Code);}
    [Fact]public void PersonalAcceptanceNeedsClearOriginalAndPreservesMembership(){var s=Start(true);Succeed(s);Assert.Equal(ResultCode.NotAvailable,s.ManageHouseholdService(new(new("request:no-cycle-accept"),HouseholdServiceAction.AcceptPledge,Owner,Old),Heir,s.Revision).Code);var b=s.HouseholdServiceView()!.Releases.Single();Good(s.ManageHouseholdService(new(new("request:accept-release"),HouseholdServiceAction.Release,Owner,b.Other,b.Source),Heir,s.Revision));var w=s.DiagnosticSnapshot();s=new(w);var prior=ContractJson.Write(w.Memberships);var i=new HouseholdServiceInput(new("request:accept-local"),HouseholdServiceAction.AcceptPledge,Owner,Old);Assert.Equal(ResultCode.NotAvailable,s.ManageHouseholdService(i,Old,s.Revision).Code);Good(s.ManageHouseholdService(i,Heir,s.Revision));Assert.Equal(prior,ContractJson.Write(s.DiagnosticSnapshot().Memberships));{Assert.Equal(ResultCode.AlreadyAccepted,s.ManageHouseholdService(i,Heir,s.Revision).Code);Assert.Contains(s.DiagnosticSnapshot().ServiceBonds,b=>b.Subject==Old&&b.Target==Heir&&b.Until==long.MaxValue);}new WorldSession(s.DiagnosticSnapshot());}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]public void TamperedReappointmentCannotLoad(int n){var s=Prepared();var i=Renew(s,s.DiagnosticSnapshot().Castellan!.Entries[0].Input.Id);Good(s.ManageCastellan(i,Old,s.Revision));var w=s.DiagnosticSnapshot();var e=w.Castellan!.Entries[^1];w.Castellan.Entries[^1]=n switch{0=>e with{Until=e.Until+1},1=>e with{Principal=Old},2=>e with{Input=e.Input with{Appointment=null}},_=>e with{Input=e.Input with{Person=Heir}}};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)]public void ActualSaveRecoveryAndFutureRemainIdentical(int phase){var s=Start(phase>=4);var old=Appoint(s);Good(s.ManageCastellan(old,s.PlayerControl,s.Revision));if(phase>0)Succeed(s);if(phase>=2)Service(s);if(phase>=3){var fresh=Renew(s,old.Id);Good(s.ManageCastellan(fresh,s.PlayerControl,s.Revision));if(phase==3){Good(s.ManageCastellan(new(new("request:saved-custody"),CastellanAction.ReceiveStore,Home,Appointment:fresh.Id),Old,s.Revision));Good(s.SendCastellanReport(new(new("request:saved-custody-paper"),CastellanReportAction.Report,fresh.Id),Old,s.Revision));}if(phase==5)Good(s.ManageCastellan(new(new("request:saved-released"),CastellanAction.Release,Home,Appointment:fresh.Id),Heir,s.Revision));}Save(s,"castle-succession-"+phase);}
    static void Save(WorldSession s,string name){s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"castle-succession-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"castellan",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("castellan"),host.Current,host.Current.Revision));var c=host.Current;Assert.Equal(ContractJson.Write(w),ContractJson.Write(c.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(s.CastellanView()),ContractJson.Write(c.CastellanView()));Assert.Equal(ContractJson.Write(s.CastellanReportsView()),ContractJson.Write(c.CastellanReportsView()));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){File.WriteAllBytes(Path.Combine(dir,name+".before.json"),ContractJson.Write(w));File.WriteAllBytes(Path.Combine(dir,name+".restored.json"),ContractJson.Write(c.DiagnosticSnapshot()));}foreach(var x in new[]{s,c})At(x,x.Seconds+10);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(c.DiagnosticSnapshot()));}

    static void Move(WorldSession s,string node){Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:castellan-trip/"+s.Revision,node),s.Revision));At(s,s.Seconds+2);At(s,s.DiagnosticSnapshot().Branches!.Journeys.Last(j=>j.Actor==s.PlayerControl).Legs[^1].EndAt+1);}
    [Fact]public void ChangedCastellanDoesNotResetSharedMonthlyWater(){var s=Start();var i=Appoint(s);Good(s.ManageCastellan(i,Old,s.Revision));Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:old-castellan-head-away","castle"),s.Revision));At(s,86400);Assert.Contains(s.DiagnosticSnapshot().Communities!.Orders,o=>o.Actor==Heir&&o.Input.Site==Home&&o.Input.Action==EconomyAction.ImproveWater&&o.Input.Amount==200);At(s,s.DiagnosticSnapshot().Branches!.Journeys.Single(j=>j.Actor==Old).Legs[^1].EndAt+1);Move(s,"kofu");Succeed(s);Service(s);Good(s.ManageCastellan(Renew(s,i.Id),Old,s.Revision));var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.ManageCommunity(new(new("request:no-reset-water-castellan"),Home,EconomyAction.ImproveWater,200),Old,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void NpcNewCastellanReportsToNewHeadWhileHeadTravels(){var s=Prepared(true);var i=Renew(s,s.DiagnosticSnapshot().Castellan!.Entries[0].Input.Id);Good(s.ManageCastellan(i,Heir,s.Revision));Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:new-castellan-head-away","castle"),s.Revision));At(s,86400);var w=s.DiagnosticSnapshot();Assert.Contains(w.CommunityAdministration!.Decisions,d=>d.Actor==Old&&d.Site==Home);Assert.DoesNotContain(w.CommunityAdministration.Decisions,d=>d.Actor==Heir);Assert.Contains(w.CastellanReports!.Papers,p=>p.Appointment==i.Id&&p.Sender==Old&&p.Recipient==Heir);Assert.Empty(s.CastellanReportsView()!.Reports);new WorldSession(w);}
    [Fact]public void UnwillingHouseholdMemberCannotBeAcceptedAsPersonalVassal(){var id=new EntityId("created:unwilling-house-vassal");var basis=NewGameWorld.Scenario(HistoricalStartCatalog.Current);var people=NewGameWorld.Normalize([NewGameWorldTests.Officer(id.Value,StartTemplate.Retainer,Home.Value,Old.Value)]);var request=new WorldSetupRequest(people,[]);var preview=NewGameSetup.Preview(basis,request);var scenario=NewGameSetup.Confirm(basis,request,preview);var w=NewGameWorld.Create(scenario,people,Heir.Value,42,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:HouseSuccession.Policy);w.Characters=w.Characters.Select(c=>c.Id==id?c with{WillObey=false}:c).ToArray();var s=new WorldSession(w);Succeed(s);var before=ContractJson.Write(s.DiagnosticSnapshot());var result=s.ManageHouseholdService(new(new("request:unwilling-personal-accept"),HouseholdServiceAction.AcceptPledge,Owner,id),Heir,s.Revision);Assert.Equal(ResultCode.NotAvailable,result.Code);Assert.Contains("同意",result.VisibleReason);Assert.DoesNotContain(id,s.HouseholdPledgeCandidates());Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void ReappointmentCannotBorrowALaterSameSecondPersonalAgreement(){var s=Start();var old=Appoint(s);Good(s.ManageCastellan(old,Old,s.Revision));Succeed(s);var before=s.Revision;Service(s);Good(s.ManageCastellan(Renew(s,old.Id),Old,s.Revision));var w=s.DiagnosticSnapshot();w.Castellan!.Entries[^1]=w.Castellan.Entries[^1] with{Revision=before};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void AcceptedNpcPersonalSourceCannotBeForged(){var s=Prepared(true);var w=s.DiagnosticSnapshot();w.HouseService!.Entries[^1]=w.HouseService.Entries[^1] with{Subject=Heir};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
}
